svg.script:
const byId = id => document.getElementById(id);
const map = byId("map"), student = byId("student");
const coldMethod = byId("cold-method"), lateMethod = byId("method");
const step = byId("step"), play = byId("play");
const handoff = 14, end = Number(step.max);
const colors = { sft: "var(--teal)", opd: "var(--rust)" };
const initial = [65, 147], routes = [[272, 145], [345, 58]], sigma = [21, 16];
const midpoint = routes[0].map((a, k) => (a + routes[1][k]) / 2);
const mix = (a, b, t) => a.map((v, k) => v + (b[k] - v) * t);
const translate = ([x, y]) => "translate(" + x + " " + y + ")";

// All method combinations share the same normal draws at each step.
let seed = 20260726;
function uniform() {
  seed = (Math.imul(1664525, seed) + 1013904223) >>> 0;
  return (seed + 0.5) / 4294967296;
}
const batches = Array.from({length: end + 1}, () => {
  const offsets = [];
  for (let i = 0; i < 12; i++) {
    const r = Math.sqrt(-2 * Math.log(uniform())), angle = 2 * Math.PI * uniform();
    const u = r * Math.cos(angle), v = r * Math.sin(angle);
    offsets.push([u, v], [-u, -v]);
  }
  return offsets;
});
const gateX = 165, openRadius = 3, verifyRadius = 2;
// Standard normal CDF (A&S 26.2.17). The whole half-plane below the gate
// is observed as one action, so its likelihood is its integrated mass.
function directMass(meanX) {
  const z = (gateX - meanX) / sigma[0], t = 1 / (1 + 0.2316419 * Math.abs(z));
  const poly = t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
  const tail = Math.exp(-0.5 * z * z) * poly / Math.sqrt(2 * Math.PI);
  return z < 0 ? tail : 1 - tail;
}
const teacherDirect = (directMass(routes[0][0]) + directMass(routes[1][0])) / 2;
function batch(mean, offsets) {
  const directScore = Math.log(teacherDirect / directMass(mean[0]));
  return offsets.map(([u, v]) => {
    const x = mean[0] + u * sigma[0], y = mean[1] + v * sigma[1];
    const [a, b] = routes.map(([cx, cy]) => -0.5 * (((x - cx) / sigma[0]) ** 2 + ((y - cy) / sigma[1]) ** 2));
    const high = Math.max(a, b);
    const distanceSquared = -2 * high;
    const searched = x >= gateX;
    const verified = searched && distanceSquared <= verifyRadius ** 2;
    const signal = searched
      ? high + Math.log((Math.exp(a - high) + Math.exp(b - high)) / 2) + (u * u + v * v) / 2
      : directScore;
    return { x, y, offset: [u, v], signal, distanceSquared, searched, verified };
  });
}
function averageSignal(points) {
  const first = points[0].signal;
  return first + points.reduce((sum, p) => sum + (p.signal - first), 0) / points.length;
}
function trajectory(first, second, steps = end) {
  const means = [initial];
  for (let t = 0; t < steps; t++) {
    const mean = means[t];
    const mode = t < handoff ? first : second;
    if (mode === "sft") {
      // Fixed covariance: the forward-KL mean update points to the demo mean.
      means.push(mix(mean, midpoint, 0.15));
      continue;
    }
    const points = batch(mean, batches[t]), baseline = averageSignal(points);
    // Score-function update in standardized coordinates, using the displayed batch.
    means.push(mean.map((m, k) => m + 0.16 * sigma[k] * points.reduce(
      (sum, p) => sum + p.offset[k] * (p.signal - baseline), 0) / points.length));
  }
  return means;
}
for (const mode of ["sft", "opd"]) {
  const mean = trajectory(mode, mode, handoff)[handoff];
  const probe = batch(mean, batches[handoff]);
  const count = probe.filter(p => p.verified).length;
  const score = byId("score-" + mode);
  score.value = count + "/" + probe.length;
  score.parentElement.style.setProperty("--fraction", (100 * count / probe.length) + "%");
}
document.querySelector(".benchmark").hidden = false;
const dots = batches[0].map(() => byId("samples").appendChild(document.createElementNS(map.namespaceURI, "circle")));
const pulls = byId("pulls").children;
const studentCells = byId("student-reach").querySelectorAll("td");
function drawCoverage(points, mode) {
  const counts = [points.filter(p => p.searched).length,
    points.filter(p => p.searched && p.distanceSquared <= openRadius ** 2).length,
    points.filter(p => p.verified).length];
  counts.forEach((n, i) => {
    const percent = Math.round(100 * n / points.length) + "%";
    const cell = studentCells[i + 1];
    if (cell.textContent !== percent) {
      cell.textContent = percent;
      cell.style.setProperty("--reach", percent);
    }
  });
  byId("teacher-reach").classList.toggle("training", mode === "sft");
  byId("student-reach").classList.toggle("training", mode !== "sft");
  byId("feedback-mode").textContent = mode.toUpperCase();
  const [searched, opened, verified] = counts;
  let message;
  if (mode === "sft") {
    message = verified ? "两条路径的示范都包含检验结果这一步。" : "学生尚未检验结果，示范已覆盖这一步。";
  } else if (verified) {
    message = "学生已开始检验结果，教师可以在这里纠错。";
  } else if (opened || searched) {
    message = "教师能评价已走过的步骤，学生尚未检验结果。";
  } else {
    message = "全批都直接作答，教师评分相同，峰心不动。";
  }
  byId("feedback").textContent = message;
}
const path = points => "M" + points.map(p => p.join(" ")).join("L");
const show = (id, visible) => byId(id).setAttribute("display", visible ? "inline" : "none");
let means = trajectory(coldMethod.value, lateMethod.value), time = 0, frame = 0;
function draw(t) {
  time = t;
  const k = Math.floor(t), phaseTwo = t >= handoff;
  const mode = phaseTwo ? lateMethod.value : coldMethod.value, fixed = mode === "sft";
  const mean = mix(means[k], means[Math.min(k + 1, end)], t - k);
  student.setAttribute("transform", translate(mean));
  document.documentElement.style.setProperty("--accent", colors[mode]);
  byId("cold").setAttribute("aria-current", phaseTwo ? "false" : "step");
  byId("handoff").setAttribute("aria-current", phaseTwo ? "step" : "false");
  const coldPoints = means.slice(0, Math.min(k, handoff) + 1);
  if (!phaseTwo) coldPoints.push(mean);
  byId("cold-trail").setAttribute("d", path(coldPoints));
  byId("cold-trail").setAttribute("stroke", colors[coldMethod.value]);
  byId("late-trail").setAttribute("d", phaseTwo ? path([...means.slice(handoff, k + 1), mean]) : "");
  byId("late-trail").setAttribute("stroke", colors[lateMethod.value]);
  byId("fork").setAttribute("transform", translate(means[handoff]));
  show("fork", phaseTwo);
  show("pulls", fixed); show("demonstrations", fixed); show("samples", !fixed);
  const points = batch(mean, batches[k]);
  drawCoverage(points, mode);
  if (fixed) {
    byId("sample-label").textContent = "教师示范";
    routes.forEach((target, i) => pulls[i].setAttribute("d", path([mean, mix(mean, target, 0.83)])));
  } else {
    const baseline = averageSignal(points);
    byId("sample-label").textContent = points.some(p => p.signal > baseline) ? "学生采样 · 教师偏好亮点" : "学生采样 · 教师评分相同";
    points.forEach(({x, y, signal}, i) => {
      const favored = signal > baseline;
      dots[i].setAttribute("cx", x); dots[i].setAttribute("cy", y);
      dots[i].setAttribute("r", favored ? 2.5 : 1.8);
      dots[i].classList.toggle("favored", favored);
    });
  }
  const ahead = means[Math.min(k + 4, phaseTwo ? end : handoff)];
  show("next-move", !fixed && Math.hypot(ahead[0] - mean[0], ahead[1] - mean[1]) > 5);
  byId("next-move").setAttribute("d", path([mean, ahead]));
  byId("sample-key").style.color = colors[mode];
  step.value = k;
  step.setAttribute("aria-valuetext", (phaseTwo ? "后续 " : "冷启动 ") + mode.toUpperCase() + "，第 " + k + " 步");
  byId("count").value = k + " / " + end;
  play.textContent = frame ? "暂停" : t === end ? "重播" : "播放";
}
function seek(t) { cancelAnimationFrame(frame); frame = 0; draw(t); }
byId("cold").addEventListener("click", () => seek(0));
byId("handoff").addEventListener("click", () => seek(handoff));
function changeMethods() {
  means = trajectory(coldMethod.value, lateMethod.value);
  seek(time);
}
coldMethod.addEventListener("change", changeMethods);
lateMethod.addEventListener("change", changeMethods);
step.addEventListener("input", () => seek(Number(step.value)));
const reduced = matchMedia("(prefers-reduced-motion: reduce)");
play.addEventListener("click", () => {
  if (frame) { seek(time); return; }
  const from = time === end ? 0 : time, start = performance.now();
  function tick(now) {
    const t = Math.min(end, from + Math.max(0, now - start) / 240);
    frame = t < end ? requestAnimationFrame(tick) : 0;
    draw(reduced.matches ? Math.floor(t) : t);
  }
  frame = requestAnimationFrame(tick);
  draw(from);
});
const narrow = matchMedia("(max-width: 530px)");
function layout() {
  const small = narrow.matches, w = small ? 360 : 660, h = small ? 451 : 586;
  document.documentElement.setAttribute("viewBox", "0 0 " + w + " " + h);
  if (window.frameElement?.tagName === "OBJECT") window.frameElement.style.aspectRatio = w + " / " + h;
  byId("header").setAttribute("width", w - 28);
  map.setAttribute("width", w - 24); map.setAttribute("height", small ? 152 : 286);
  for (const id of ["legend-box", "benchmark-box", "coverage-box", "toolbar"]) byId(id).setAttribute("width", w - 32);
  byId("legend-box").setAttribute("y", small ? 205 : 340);
  byId("benchmark-box").setAttribute("y", small ? 235 : 369);
  byId("coverage-box").setAttribute("y", small ? 286 : 420);
  byId("toolbar").setAttribute("y", small ? 407 : 541);
}
narrow.addEventListener("change", layout);
layout(); draw(0);
document.querySelector(".controls").hidden = false;
